const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Sakha Republic (Yakutia), Russia - approximate bounds
  const sakha = ee.Geometry.Polygon([
    [[105, 55], [105, 73], [165, 73], [165, 55], [105, 55]]
  ]);

  const summerStart = '2021-06-01';
  const summerEnd = '2021-08-31';

  console.log('Analyzing burned forest area in Sakha Republic, summer 2021...');

  // 2. Data Acquisition & Check
  // Use MODIS Burned Area Monthly product
  const burnedCol = ee.ImageCollection('MODIS/006/MCD64A1')
    .filterDate(summerStart, summerEnd)
    .filterBounds(sakha);

  const colSize = burnedCol.size().getInfo();
  console.log(`Burned area images found: ${colSize}`);

  if (colSize === 0) {
    console.log('No burned area data for summer 2021.');
    console.log('<answer>C1</answer>');
    return;
  }

  // Get forest cover data for masking
  const forestCover = ee.Image('UMD/hansen/global_forest_change_2021_v1_9')
    .select('treecover2000');

  // Forest mask: areas with >30% tree cover in 2000
  const forestMask = forestCover.gt(30);

  // 3. Processing - Calculate burned area
  // BurnDate band: day of year of burn detection (values 1-366, 0=unburned)
  const burnedArea = burnedCol.select('BurnDate')
    .max() // Get any burn during the period
    .gt(0) // Convert to binary: 1=burned, 0=not burned
    .updateMask(forestMask) // Apply forest mask
    .clip(sakha);

  // Check for valid pixels
  const pixelCount = burnedArea.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: sakha,
    scale: 500,
    maxPixels: 1e9
  }).get('BurnDate').getInfo();

  console.log(`Valid burned forest pixels: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log('No valid burned forest pixels detected.');
    console.log('<answer>B</answer>');
    return;
  }

  // 4. Calculation - Sum burned area
  // Each MODIS pixel is 500m x 500m = 250,000 m² = 0.025 hectares
  const pixelArea = ee.Image.pixelArea().divide(10000); // Convert m² to hectares

  const totalBurnedHa = burnedArea.multiply(pixelArea).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: sakha,
    scale: 500,
    maxPixels: 1e9
  }).get('BurnDate').getInfo();

  console.log(`Total burned forest area: ${(totalBurnedHa / 1000000).toFixed(2)} million hectares`);

  // 5. Validation & Final Answer
  if (totalBurnedHa === null || totalBurnedHa === undefined || isNaN(totalBurnedHa)) {
    console.log('Calculation failed - invalid result.');
    console.log('<answer>C3</answer>');
    return;
  }

  const threshold = 6000000; // 6 million hectares

  if (totalBurnedHa >= threshold) {
    console.log(`Burned area (${(totalBurnedHa / 1000000).toFixed(2)}M ha) >= 6M ha threshold`);
    console.log('<answer>A</answer>');
  } else {
    console.log(`Burned area (${(totalBurnedHa / 1000000).toFixed(2)}M ha) < 6M ha threshold`);
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
